interface ProductsUpdateEvent extends CustomEvent {
  detail: {
    sections: {
      [key: string]: string;
    };
  };
}

class ProductGrid extends HTMLElement {
  private unsubscribe: (() => void) | undefined;
  private unsubscribePagination: (() => void) | undefined;

  constructor() {
    super();
  }

  connectedCallback(): void {
    const sectionId = this.getAttribute("data-section-id");

    if (!sectionId) {
      return;
    }

    this.unsubscribe = this.handleEvent<ProductsUpdateEvent>(
      "products:update",
      (event) => {
        const section = event.detail.sections[sectionId];

        if (!section) {
          return;
        }

        const newHtml = new DOMParser().parseFromString(section, "text/html");
        const newResults = newHtml.querySelector<HTMLElement>(
          this.tagName.toLowerCase(),
        );

        if (!newResults) {
          return;
        }

        this.replaceWith(newResults);
      },
    );

    this.unsubscribePagination = this.handleEvent<ProductsUpdateEvent>(
      "products:load-more",
      (event) => {
        const section = event.detail.sections[sectionId];

        if (!section) {
          return;
        }

        const parser = new DOMParser();
        const newHtml = parser.parseFromString(section, "text/html");
        const newProductGrid = newHtml.querySelector<ProductGrid>(
          this.tagName.toLowerCase(),
        );

        if (!newProductGrid) {
          return;
        }

        const pagination = this.querySelector<HTMLElement>("uwp-load-more");
        const newPagination =
          newProductGrid.querySelector<HTMLElement>("uwp-load-more");

        if (!pagination || !newPagination) {
          return;
        }

        const productsContainer = this.firstElementChild;
        const newProducts = newProductGrid.firstElementChild;

        if (!productsContainer || !newProducts) {
          return;
        }

        pagination.replaceWith(newPagination);

        productsContainer.insertAdjacentHTML(
          "beforeend",
          newProducts.innerHTML.trim(),
        );
      },
    );
  }

  private handleEvent<T extends CustomEvent>(
    eventName: string,
    handler: (event: T) => void,
  ): () => void {
    const boundHandler = (event: Event): void => {
      if (event instanceof CustomEvent) {
        handler(event as T);
      }
    };

    document.addEventListener(eventName, boundHandler);
    return () => document.removeEventListener(eventName, boundHandler);
  }

  disconnectedCallback(): void {
    this.unsubscribe?.();
    this.unsubscribePagination?.();
  }
}

customElements.define("uwp-product-grid", ProductGrid);
